I/ontologies/BBO#Activity", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Activity", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Work that a company or organization performs using business processes. An activity can be atomic or non-atomic (compound). The types of activities that are a part of a Process Model are: Process, Sub-Process, and Task.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Activity", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Activity", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Activity", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Activity", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CallableElement", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CallableElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "CallableElement is the abstract super class of all Activities that have been defined outside of a Process or Choreography but which can be called (or reused), by a Call Activity, from within a Process or Choreography. It MAY reference Interfaces that define the service operations that it provides. The BPMN elements that can be called by Call Activities (i.e., are CallableElements) are: Process and GlobalTask (see Figure 10.43).", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CallableElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CallableElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "CallableElement", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CallableElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CatchEvent", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CatchEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Events that catch a trigger. All Start Events and some Intermediate Events are catching Events.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CatchEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CatchEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "CatchEvent", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#CatchEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Event"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#EndEvent", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#EndEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "As the name implies, the End Event indicates where a Process will end. In terms of Sequence Flows, the End Event ends the flow of the Process, and thus, will not have any outgoing Sequence Flows—no Sequence Flow can connect from an End Event.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#EndEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#EndEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "EndEvent", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#EndEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ThrowEvent"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Event", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Event", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "An Event is something that “happens” during the course of a Process. These Events affect the flow of the Process and usually have a cause or an impact and in general require or allow for a reaction. The term “event” is general enough to cover many things in a Process. The start of an Activity, the end of an Activity, the change of state of a document, a Message that arrives, etc., all could be considered Events.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim",