language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ExclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ExclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "ExclusiveGateway", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ExclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElement", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "FlowElement is the abstract super class for all elements that can appear in a Process flow, which are FlowNodes (see page 99, which consist of Activities (see page 151), Choreography Activities (see page 321) Gateways (see page 287), and Events (see page 233), Data Objects (see page 205), Data Associations (see page 221), and Sequence Flows (see page 97).", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "FlowElement", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElementsContainer", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElementsContainer", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "/", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElementsContainer", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElementsContainer", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "FlowElementsContainer", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "The FlowNode element is used to provide a single element as the source and target Sequence Flow associations (see Figure 8.35) instead of the individual associations of the elements that can connect to Sequence Flows (see the section above). Only the Gateway, Activity, Choreography Activity, and Event elements can connect to Sequence Flows and thus, these elements are the only ones that are sub-classes of FlowNode.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "FlowNode", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowElement"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "Gateways are used to control how Sequence Flows interact as they converge and diverge within a Process. If the flow does not need to be controlled, then a Gateway is not needed. The term “Gateway” implies that there is a gating mechanism that either allows or disallows passage through the Gateway--that is, as tokens arrive at a Gateway, they can be merged together on input and/or split apart on output as the Gateway mechanisms are invoked.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Gateway", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#FlowNode"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#InclusiveGateway", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#InclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A diverging Inclusive Gateway (Inclusive Decision) can be used to create alternative but also parallel paths within a Process flow. Unlike the Exclusive Gateway, all condition Expressions are evaluated. The true evaluation of one condition Expression does not exclude the evaluation of other condition Expressions. All Sequence Flows with a true evaluation will be traversed by a token. Since each path is considered to be independent, all combinations of the paths MAY be taken, from zero to all. However, it should be designed so that at least one path is taken.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#InclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#InclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "InclusiveGateway", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#InclusiveGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ManualTask", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ManualTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A Manual Task is a Task that is expected to be performed without the aid of any business process execution engine or any application. An example of this could be a telephone technician installing a telephone at a customer location.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ManualTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ManualTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "ManualTask", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ManualTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Task"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ParallelGateway", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ParallelGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A Parallel Gateway is used to synchronize (combine) parallel flows and to create parallel flows.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ParallelGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ParallelGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "ParallelGateway", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ParallelGateway", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Gateway"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Process", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Process", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A sequence or flow of Activities in an organization with the objective of carrying out work. In BPMN, a Process is depicted as a graph of Flow Elements, which are a set of Activities, Events, Gateways, and Sequence Flow that adhere to a finite execution semantics.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Process", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4