4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Role", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "Role"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "RootElement is the abstract super class for all BPMN elements that are contained within Definitions. When contained within Definitions, these elements have their own defined life-cycle and are not deleted with the deletion of other elements. Examples of concrete RootElements include Collaboration, Process, and Choreography. Depending on their use, RootElements can be referenced by multiple other elements (i.e., they can be reused). Some RootElements MAY be contained within other elements instead of Definitions. This is done to avoid the maintenance overhead of an independent life-cycle. For example, an EventDefinition would be contained in a Process since it is used only there. In this case the EventDefinition would be dependent on the tool life-cycle of the Process.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#RootElement", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "RootElement", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "A Service Task is a Task that uses some sort of service, which could be a Web service or an automated application.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#isDefinedBy", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#label", "object": {"value": {"@value": "ServiceTask", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#ServiceTask", "predicate": "http://www.w3.org/2000/01/rdf-schema#subClassOf", "object": {"entity": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#Task"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#StartEvent", "predicate": "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", "object": {"entity": "http://www.w3.org/2002/07/owl#Class"}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_claim", "subject": "https://www.irit.fr/recherches/MELODI/ontologies/BBO#StartEvent", "predicate": "http://www.w3.org/2000/01/rdf-schema#comment", "object": {"value": {"@value": "As the name implies, the Start Event indicates where a particular Process will start. In terms of Sequence Flows, the Start Event starts the flow of the Process, and thus, will not have any incoming Sequence Flows—no Sequence Flow can connect to a Start Event. flow of the Process and does not have any incoming Sequence Flow, but can have a Trigger. The Start Event is displayed as a circle, drawn with a single thin line.", "@language": "en"}}, "evidence_type": "deterministic", "references": [{"source_uri": "file:ontology/bbo.ttl#sha256=06c245c7c69098b2a28c9a59c97ea1f1e157d41a22f0f0e10f172d185a4cf9af"}]}, {"op": "add_clai